async function addTodo(text) {
  const temp = { id: crypto.randomUUID(), text, pending: true };  // 클라가 id 생성
  localStore.put(temp);          // 로컬에 즉시 저장
  render();                      // 화면에 즉시 반영(낙관적 — 보류 표식)
  outbox.enqueue({ op: 'add', item: temp });  // 큐에 담기
  try {
    await sync();                // 뒤에서 서버 동기화
    localStore.update(temp.id, { pending: false });  // 확정
  } catch {
    localStore.update(temp.id, { error: true });     // 실패 → 되돌림·에러 표시
  }
}
// ★ id 를 클라가 만들면(UUID) 오프라인에서도 생성·참조 가능
